const pptxgen = require('pptxgenjs');

const C = {
  white: 'FFFFFF',
  off: 'F8FAFC',
  ink: '0F172A',
  slate: '334155',
  muted: '64748B',
  grid: 'CBD5E1',
  line: 'E2E8F0',
  blue: '2563EB',
  cyan: '06B6D4',
  teal: '14B8A6',
  amber: 'F59E0B',
  red: 'EF4444',
  green: '22C55E',
  purple: '7C3AED',
};

function addHeader(slide, theme, title, eyebrow = 'HTTP Archive • State of the Web') {
  slide.addText(eyebrow.toUpperCase(), {
    x: 0.45, y: 0.22, w: 5.0, h: 0.18,
    fontFace: 'Arial', fontSize: 6.8, bold: true, color: theme.accent,
    charSpace: 1.1, margin: 0,
  });
  slide.addText(title, {
    x: 0.45, y: 0.43, w: 8.7, h: 0.45,
    fontFace: 'Arial', fontSize: 17.5, bold: true, color: theme.primary,
    margin: 0, breakLine: false, fit: 'shrink',
  });
  slide.addShape(pptxgen.ShapeType.line, {
    x: 0.45, y: 0.97, w: 9.1, h: 0,
    line: { color: C.line, width: 1 },
  });
}

function addBadge(slide, pres, theme, n) {
  slide.addShape(pres.ShapeType.ellipse, {
    x: 9.28, y: 5.08, w: 0.36, h: 0.36,
    fill: { color: theme.accent, transparency: 6 },
    line: { color: theme.accent, transparency: 100 },
  });
  slide.addText(String(n), {
    x: 9.28, y: 5.155, w: 0.36, h: 0.12,
    fontFace: 'Arial', fontSize: 7, bold: true, color: C.white,
    align: 'center', margin: 0,
  });
}

function addSource(slide, text = 'Source: HTTP Archive State of the Web report, Jan 2020–Mar 2026.') {
  slide.addText(text, {
    x: 0.45, y: 5.16, w: 6.9, h: 0.16,
    fontFace: 'Arial', fontSize: 6.6, color: C.muted, margin: 0,
  });
}

function addMetricCard(slide, x, y, w, h, label, value, delta, color) {
  slide.addShape(pptxgen.ShapeType.roundRect, {
    x, y, w, h,
    rectRadius: 0.08,
    fill: { color: C.white },
    line: { color: 'DDE6F3', width: 0.8 },
    shadow: { type: 'outer', color: 'D5DDE8', opacity: 0.13, blur: 1, angle: 45, distance: 1 },
  });
  slide.addText(label.toUpperCase(), { x: x + 0.16, y: y + 0.14, w: w - 0.32, h: 0.16, fontSize: 6.8, bold: true, color: C.muted, charSpace: 0.6, margin: 0 });
  slide.addText(value, { x: x + 0.16, y: y + 0.43, w: w - 0.32, h: 0.45, fontSize: 24, bold: true, color, margin: 0, fit: 'shrink' });
  slide.addText(delta, { x: x + 0.16, y: y + 0.93, w: w - 0.32, h: 0.28, fontSize: 7.5, color: C.slate, margin: 0, fit: 'shrink' });
}

function addLineChart(slide, pres, cfg) {
  const { x, y, w, h, series, yMin, yMax, yTicks, labels, title, suffix = '', colors = [C.blue, C.cyan], showLegend = true } = cfg;
  slide.addShape(pres.ShapeType.roundRect, { x, y, w, h, rectRadius: 0.06, fill: { color: C.white }, line: { color: 'DDE6F3', width: 0.8 } });
  if (title) slide.addText(title, { x: x + 0.15, y: y + 0.12, w: w - 0.3, h: 0.18, fontSize: 8, bold: true, color: C.ink, margin: 0 });
  const px = x + 0.48, py = y + 0.52, pw = w - 0.78, ph = h - 0.95;
  const ticks = yTicks || [yMin, (yMin + yMax) / 2, yMax];
  ticks.forEach(t => {
    const yy = py + ph - ((t - yMin) / (yMax - yMin)) * ph;
    slide.addShape(pres.ShapeType.line, { x: px, y: yy, w: pw, h: 0, line: { color: C.line, width: 0.55 } });
    slide.addText(`${t}${suffix}`, { x: x + 0.08, y: yy - 0.07, w: 0.34, h: 0.12, fontSize: 5.7, color: C.muted, align: 'right', margin: 0 });
  });
  labels.forEach((lab, i) => {
    const xx = px + (labels.length === 1 ? 0 : (i / (labels.length - 1)) * pw);
    slide.addShape(pres.ShapeType.line, { x: xx, y: py, w: 0, h: ph, line: { color: 'F1F5F9', width: 0.45 } });
    slide.addText(lab, { x: xx - 0.25, y: py + ph + 0.08, w: 0.5, h: 0.12, fontSize: 5.7, color: C.muted, align: 'center', margin: 0 });
  });
  series.forEach((s, sIdx) => {
    const col = s.color || colors[sIdx % colors.length];
    const points = s.values.map((v, i) => ({ xx: px + (labels.length === 1 ? 0 : (i / (labels.length - 1)) * pw), yy: py + ph - ((v - yMin) / (yMax - yMin)) * ph }));
    for (let i = 0; i < points.length - 1; i++) {
      slide.addShape(pres.ShapeType.line, { x: points[i].xx, y: points[i].yy, w: points[i + 1].xx - points[i].xx, h: points[i + 1].yy - points[i].yy, line: { color: col, width: 2.1, beginArrowType: 'none', endArrowType: 'none' } });
    }
    points.forEach(p => slide.addShape(pres.ShapeType.ellipse, { x: p.xx - 0.035, y: p.yy - 0.035, w: 0.07, h: 0.07, fill: { color: col }, line: { color: C.white, width: 0.5 } }));
  });
  if (showLegend) {
    series.forEach((s, i) => {
      const lx = x + w - 1.35 + i * 0.65;
      slide.addShape(pres.ShapeType.line, { x: lx, y: y + 0.18, w: 0.18, h: 0, line: { color: s.color || colors[i % colors.length], width: 2 } });
      slide.addText(s.name, { x: lx + 0.22, y: y + 0.11, w: 0.43, h: 0.14, fontSize: 5.8, color: C.slate, margin: 0 });
    });
  }
}

function addBarChart(slide, pres, cfg) {
  const { x, y, w, h, title, groups, yMax, suffix = '', colors = [C.blue, C.cyan, C.amber] } = cfg;
  slide.addShape(pres.ShapeType.roundRect, { x, y, w, h, rectRadius: 0.06, fill: { color: C.white }, line: { color: 'DDE6F3', width: 0.8 } });
  if (title) slide.addText(title, { x: x + 0.15, y: y + 0.12, w: w - 0.3, h: 0.18, fontSize: 8, bold: true, color: C.ink, margin: 0 });
  const px = x + 0.45, py = y + 0.5, pw = w - 0.7, ph = h - 0.95;
  [0, yMax / 2, yMax].forEach(t => {
    const yy = py + ph - (t / yMax) * ph;
    slide.addShape(pres.ShapeType.line, { x: px, y: yy, w: pw, h: 0, line: { color: C.line, width: 0.5 } });
    slide.addText(`${Math.round(t)}${suffix}`, { x: x + 0.08, y: yy - 0.07, w: 0.32, h: 0.12, fontSize: 5.5, color: C.muted, align: 'right', margin: 0 });
  });
  const groupW = pw / groups.length;
  groups.forEach((g, gi) => {
    const barW = Math.min(0.22, (groupW - 0.16) / g.values.length);
    const startX = px + gi * groupW + (groupW - barW * g.values.length) / 2;
    g.values.forEach((v, vi) => {
      const bh = (v.value / yMax) * ph;
      const bx = startX + vi * barW;
      slide.addShape(pres.ShapeType.rect, { x: bx, y: py + ph - bh, w: barW * 0.72, h: bh, fill: { color: v.color || colors[vi % colors.length] }, line: { color: v.color || colors[vi % colors.length], transparency: 100 } });
      slide.addText(v.label, { x: bx - 0.03, y: py + ph - bh - 0.16, w: barW * 0.95, h: 0.12, fontSize: 5.8, color: C.slate, bold: true, align: 'center', margin: 0 });
    });
    slide.addText(g.name, { x: px + gi * groupW, y: py + ph + 0.08, w: groupW - 0.02, h: 0.15, fontSize: 5.8, color: C.muted, align: 'center', margin: 0 });
  });
}

function addBullet(slide, text, x, y, w, color = C.slate) {
  slide.addShape(pptxgen.ShapeType.ellipse, { x, y: y + 0.045, w: 0.055, h: 0.055, fill: { color: C.amber }, line: { color: C.amber } });
  slide.addText(text, { x: x + 0.13, y, w, h: 0.28, fontSize: 8.2, color, margin: 0, fit: 'shrink', breakLine: false });
}

module.exports = { C, addHeader, addBadge, addSource, addMetricCard, addLineChart, addBarChart, addBullet };
EOF
